"""Independently reconcile the six control/omission diagnostic JVMs from raw data.

The only imported helper is this directory's independently written stdlib raw
checker. No experiment runner or diagnostic analyzer is imported or trusted.
"""
import argparse
import importlib.util
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
CHECKER = HERE / 'check-discovery-raw.py'
spec = importlib.util.spec_from_file_location('independent_raw_check', CHECKER)
raw = importlib.util.module_from_spec(spec)
spec.loader.exec_module(raw)
MASKS = {'fanout': ['measurement', 'reading'], 'shared-tail': ['l0', 'l1']}
OUTPUT_PROPERTY = 'rdf4j.lmdb.publicationDiagnostic.output'
MASK_PROPERTY = 'rdf4j.lmdb.resultCoordinates.experiment.omitFactorTargets'
LIMIT_PROPERTY = 'rdf4j.lmdb.queryMemory.perQueryMaxBytes'
VARIABLE_PROPERTIES = [OUTPUT_PROPERTY, MASK_PROPERTY, LIMIT_PROPERTY]
SUITES = {
    'original512': (536870912, '', ['fanout', 'shared-tail']),
    'overlay-all512': (536870912, '', ['fanout', 'shared-tail']),
    'overlay-fanout-omit512': (536870912, 'measurement,reading', ['fanout']),
    'overlay-shared-omit512': (536870912, 'l0,l1', ['shared-tail']),
    'overlay-shared-all256': (268435456, '', ['shared-tail']),
    'overlay-shared-omit256': (268435456, 'l0,l1', ['shared-tail'])}


def load_json(path, sources):
    path = Path(path).resolve(strict=True)
    sources[str(path)] = raw.digest(path)
    return json.loads(path.read_text())


def normalize_metadata(metadata):
    result = dict(metadata)
    for key in ('source', 'arm', 'store', 'perQueryLedgerLimitBytes'):
        result.pop(key, None)
    result['systemProperties'] = {k: v for k, v in result['systemProperties'].items() if k not in VARIABLE_PROPERTIES}
    result['jvmArguments'] = [v for v in result['jvmArguments']
        if not any(v.startswith('-D' + key + '=') for key in VARIABLE_PROPERTIES)]
    return result


def route(sample):
    counters = sample['counters']
    return {'selections': sample['successfulSelections'],
        'counters': {k: counters[k] for k in ('irOpened', 'irRows', 'semanticNativeCompiles',
            'compiledBinds', 'interpretedBinds', 'aggregateCompiledBinds', 'aggregateInterpretedBinds')},
        'adjacency': sample['adjacency']}


def collect(suite_root, name, sources):
    folder = suite_root / name
    limit, mask, fixtures = SUITES[name]
    plan = load_json(folder / 'protocol.json', sources)
    raw.require(plan['name'] == name and plan['queryLimitBytes'] == limit and plan['mask'] == mask
        and set(plan['fixtures']) == set(fixtures) and plan['warmup'] == 3 and plan['iterations'] == 1,
        'Prescribed diagnostic suite changed: ' + name)
    runtime = load_json(plan['runtime'], sources)
    raw.require(raw.digest(plan['runtime']) == plan['runtimeSha256'] and runtime['diagnosticOnly']
        and runtime['extraWeakDereferences'] == 0, 'Diagnostic runtime identity differs')
    for field, hash_field in [('baseRuntimeDescriptor', 'baseRuntimeDescriptorSha256'),
            ('sourceGenerationFile', 'sourceGenerationSha256'), ('classpathFile', 'classpathFileSha256'),
            ('classpathManifestFile', 'classpathManifestSha256')]:
        path = Path(runtime[field]).resolve(strict=True)
        sources[str(path)] = raw.digest(path)
        raw.require(sources[str(path)] == runtime[hash_field], 'Runtime companion changed: ' + str(path))
    if name != 'original512':
        raw.require(runtime['maskGuardPresent'], 'Control suite lacks experimental publication guard')
    result = {'plan': plan, 'runtime': runtime, 'fixtures': {}}
    for fixture in fixtures:
        run_folder = folder / 'runs' / fixture
        command = load_json(run_folder / 'command.json', sources)
        process = load_json(run_folder / 'process-result.json', sources)
        raw.require(process['exitCode'] == 0 and not process.get('timedOut', False), 'Diagnostic JVM failed')
        raw.require(command['runtimeSha256'] == plan['runtimeSha256']
            and command['protocolSha256'] == sources[str((folder / 'protocol.json').resolve())],
            'Recorded command used a different protocol/runtime')
        argv = command['argv']
        cp_at = argv.index('-cp')
        expected_jvm = plan['jvmArguments'] + ['-D' + OUTPUT_PROPERTY + '=' + str(run_folder / 'page-records'),
            '-D' + LIMIT_PROPERTY + '=' + str(limit), '-Drdf4j.lmdb.resultCoordinateTransport=dense']
        if runtime['maskGuardPresent']:
            expected_jvm.append('-D' + MASK_PROPERTY + '=' + mask)
        raw.require(argv[0] == plan['java'] and argv[1:cp_at] == expected_jvm
            and argv[cp_at + 1] == Path(runtime['classpathFile']).read_text().strip(),
            'Recorded Java options/classpath differ from frozen diagnostic runtime')
        independent = raw.inspect_fixture(folder, fixture, plan, sources)
        records = raw.read_jsonl(folder / 'runs' / fixture / 'samples.jsonl', sources)
        metadata, samples = records[0], records[1:]
        raw.require(metadata['jvmArguments'] == expected_jvm, 'Observed JVM options differ from launch command')
        raw.require(metadata['systemProperties'][LIMIT_PROPERTY] == str(limit), 'Budget property mismatch')
        if name != 'original512':
            raw.require(metadata['systemProperties'][MASK_PROPERTY] == mask, 'Mask property mismatch')
        page_keys = []
        for index in range(1, 5):
            records = raw.read_jsonl(folder / 'runs' / fixture / 'page-records' / f'owner-{index}.jsonl', sources)
            pages = [r for r in records if r['type'] == 'page']
            page_keys.append({tuple(p[k] for k in ('target', 'namespace', 'group', 'parent', 'column', 'pageIndex'))
                              for p in pages})
        result['fixtures'][fixture] = {'independent': independent, 'metadata': metadata,
            'normalizedMetadata': normalize_metadata(metadata), 'samples': samples, 'pageKeys': page_keys}
    return result


def pair_queries(left, right):
    for index, (a, b) in enumerate(zip(left['independent']['queries'], right['independent']['queries'], strict=True)):
        raw.require(a['iteration'] == b['iteration'] and a['stage'] == b['stage'], 'Paired query chronology differs')
        raw.require(left['normalizedMetadata'] == right['normalizedMetadata'], 'Paired fixture/JVM metadata differs')
        raw.require(route(left['samples'][index]) == route(right['samples'][index]), 'Paired route/tier/adjacency differs')
        yield index, a, b


def compare_original(original, all_enabled, fixture):
    observations = []
    for index, a, b in pair_queries(original, all_enabled):
        raw.require(a['resolverCalls'] == b['resolverCalls'], 'All-enabled overlay changed resolver calls')
        raw.require(a['totals'] == b['totals'], 'All-enabled overlay changed operation totals')
        raw.require(a['banks'] == b['banks'], 'All-enabled overlay changed per-bank counts or page accounting')
        raw.require(original['pageKeys'][index] == all_enabled['pageKeys'][index],
                    'All-enabled overlay changed complete factor-page keys')
        observations.append({'iteration': a['iteration'], 'stage': a['stage'], 'resolverCalls': a['resolverCalls'],
            'ordinaryHits': a['totals']['ordinaryHit'], 'factorHits': a['totals']['factorHit'],
            'pageCount': a['distinctPageKeys'], 'pageChargeBytes': a['pageChargeBytes'],
            'originalLedgerPeak': a['ledgerPeakBytes'], 'overlayLedgerPeak': b['ledgerPeakBytes'],
            'allCountersAndPageKeysEqual': True, 'routeTierAdjacencyEqual': True})
    return {'fixture': fixture, 'passed': True, 'queries': observations}


def compare_omission(all_enabled, omitted, fixture):
    mask = MASKS[fixture]
    indices = {raw.EXPECTED[fixture]['names'].index(name) for name in mask}
    observations = []
    for index, a, b in pair_queries(all_enabled, omitted):
        raw.require(a['resolverCalls'] == b['resolverCalls'], 'Omission changed resolver calls at 512 MiB')
        for counter in ('ordinaryHit', 'factorHit', 'find', 'rememberCall', 'publicationCall'):
            raw.require(a['totals'][counter] == b['totals'][counter], 'Omission changed preserved traffic: ' + counter)
        raw.require(a['totals']['pageRefused'] == b['totals']['pageRefused'] == 0, '512 MiB admission refusal')
        omitted_calls = sum(a['banks'][name]['totals']['publicationCall'] for name in mask)
        removed_pages = sum(a['banks'][name]['finalPages'] for name in mask)
        removed_bytes = sum(a['banks'][name]['finalPageBytes'] for name in mask)
        for name in raw.EXPECTED[fixture]['names']:
            before, after = a['banks'][name], b['banks'][name]
            for counter in ('ordinaryHit', 'factorHit', 'find', 'rememberCall', 'publicationCall'):
                raw.require(before['totals'][counter] == after['totals'][counter], 'Per-target preserved traffic differs')
            if name in mask:
                raw.require(after['totals']['publicationSkipped'] == after['totals']['publicationCall'],
                            'Selected target did not skip every publication')
                raw.require(before['totals']['factorHit'] == after['totals']['factorHit'] == 0,
                            'Selected target had a useful factor hit')
                raw.require(all(after['totals'][k] == 0 for k in ('publicationComplete', 'publicationWrite',
                    'pageAttempt', 'pageAdmitted', 'pageRefused', 'pageBytesGranted', 'pageBytesReleased', 'pagesReleased'))
                    and after['finalPages'] == after['finalPageBytes'] == 0, 'Selected bank still publishes or owns pages')
            else:
                for counter in ('publicationComplete', 'publicationWrite', 'publicationSkipped', 'pageAdmitted',
                                'pageBytesGranted', 'pageBytesReleased', 'pagesReleased'):
                    raw.require(before['totals'][counter] == after['totals'][counter], 'Unselected bank changed: ' + counter)
                raw.require(before['finalPages'] == after['finalPages']
                    and before['finalPageBytes'] == after['finalPageBytes'], 'Unselected page accounting changed')
        raw.require(b['totals']['publicationSkipped'] == omitted_calls, 'Global omitted-call total differs')
        expected_keys = {key for key in all_enabled['pageKeys'][index] if key[0] not in indices}
        raw.require(expected_keys == omitted['pageKeys'][index], 'Surviving full page keys changed')
        raw.require(a['distinctPageKeys'] - b['distinctPageKeys'] == removed_pages
            and a['pageChargeBytes'] - b['pageChargeBytes'] == removed_bytes, 'Removed page charge/count differs')
        observations.append({'iteration': a['iteration'], 'stage': a['stage'], 'resolverCalls': a['resolverCalls'],
            'ordinaryHits': a['totals']['ordinaryHit'], 'factorHits': a['totals']['factorHit'],
            'allPublicationCalls': a['totals']['publicationCall'], 'skippedPublicationCalls': omitted_calls,
            'removedPages': removed_pages, 'removedPageBytes': removed_bytes,
            'allPageCount': a['distinctPageKeys'], 'omitPageCount': b['distinctPageKeys'],
            'allPageBytes': a['pageChargeBytes'], 'omitPageBytes': b['pageChargeBytes'],
            'allLedgerPeak': a['ledgerPeakBytes'], 'omitLedgerPeak': b['ledgerPeakBytes'],
            'resolverAndHitCountsEqual': True, 'routeTierAdjacencyEqual': True,
            'unselectedFullPageKeysEqual': True, 'noFactorAdmissionRefusals': True})
    return {'fixture': fixture, 'mask': mask, 'passed': True, 'queries': observations}


def compare_budget(all256, omit256, all512, omit512):
    observations = []
    right_names = ['r0', 'r1']
    for index, a, b in pair_queries(all256, omit256):
        c = all512['independent']['queries'][index]
        d = omit512['independent']['queries'][index]
        raw.require(route(all256['samples'][index]) == route(all512['samples'][index])
            == route(omit512['samples'][index]), 'Budget comparison route/tier differs')
        raw.require(a['totals']['ordinaryHit'] == b['totals']['ordinaryHit'] == c['totals']['ordinaryHit'],
                    'Budget comparison changed ordinary hits')
        raw.require(a['totals']['pageRefused'] > 0 and b['totals']['pageRefused'] == 0,
                    'Expected normal-budget refusal and omission relief not observed')
        raw.require(b['resolverCalls'] == d['resolverCalls'] == c['resolverCalls']
            and b['totals']['factorHit'] == d['totals']['factorHit'] == c['totals']['factorHit'],
            'Omission at 256 MiB did not recover uncapped resolver/hit counts')
        raw.require(b['banks'] == d['banks'] and omit256['pageKeys'][index] == omit512['pageKeys'][index],
                    'Omitted 256/512 bank counts or full page keys differ')
        per_target = {}
        for name in raw.EXPECTED['shared-tail']['names']:
            old, new = a['banks'][name], b['banks'][name]
            per_target[name] = {'all256Pages': old['finalPages'], 'omit256Pages': new['finalPages'],
                'additionalPages': new['finalPages'] - old['finalPages'],
                'all256FactorHits': old['totals']['factorHit'], 'omit256FactorHits': new['totals']['factorHit'],
                'additionalFactorHits': new['totals']['factorHit'] - old['totals']['factorHit']}
        raw.require(all(per_target[name]['additionalPages'] >= 0 for name in right_names),
                    'Right-side admitted pages decreased under normal-budget omission')
        raw.require(a['resolverCalls'] - b['resolverCalls'] == b['totals']['factorHit'] - a['totals']['factorHit'],
                    'Resolver relief differs from additional factor hits')
        observations.append({'iteration': a['iteration'], 'stage': a['stage'],
            'all256ResolverCalls': a['resolverCalls'], 'omit256ResolverCalls': b['resolverCalls'],
            'additionalFactorHits': b['totals']['factorHit'] - a['totals']['factorHit'],
            'all256PageRefusals': a['totals']['pageRefused'], 'omit256PageRefusals': b['totals']['pageRefused'],
            'all256PageCount': a['distinctPageKeys'], 'omit256PageCount': b['distinctPageKeys'],
            'all256LedgerPeak': a['ledgerPeakBytes'], 'omit256LedgerPeak': b['ledgerPeakBytes'],
            'perTarget': per_target, 'omit256MatchesOmit512TrafficAndPageKeys': True})
    return {'fixture': 'shared-tail', 'passed': True, 'queries': observations,
        'interpretation': 'Same overlay diagnostics at both budgets. Admission relief and publication removal are combined at 256 MiB. No timing or allocation inference.'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--suite-root', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--selection-output', type=Path)
    args = parser.parse_args()
    sources = {}
    suites = {name: collect(args.suite_root.resolve(strict=True), name, sources) for name in SUITES}
    following = [value for name, value in suites.items() if name != 'original512']
    raw.require(len({value['plan']['runtimeSha256'] for value in following}) == 1
        and len({value['plan']['sourceIdentity'] for value in following}) == 1,
        'Control and omission suites do not share exact diagnostic runtime/source')
    references, ablations = {}, {}
    for fixture in raw.EXPECTED:
        original = suites['original512']['fixtures'][fixture]
        all512 = suites['overlay-all512']['fixtures'][fixture]
        omit_key = 'overlay-fanout-omit512' if fixture == 'fanout' else 'overlay-shared-omit512'
        omit512 = suites[omit_key]['fixtures'][fixture]
        references[fixture] = compare_original(original, all512, fixture)
        ablations[fixture] = compare_omission(all512, omit512, fixture)
    budget = compare_budget(suites['overlay-shared-all256']['fixtures']['shared-tail'],
        suites['overlay-shared-omit256']['fixtures']['shared-tail'],
        suites['overlay-all512']['fixtures']['shared-tail'],
        suites['overlay-shared-omit512']['fixtures']['shared-tail'])
    result = {'format': 1, 'valid': True, 'scriptSha256': raw.digest(__file__),
        'independentRawCheckerFile': str(CHECKER), 'independentRawCheckerSha256': raw.digest(CHECKER),
        'sourceFiles': sources, 'fixtureMasks': MASKS,
        'originalReference': references, 'publicationAblation512': ablations, 'sharedTailBudget': budget,
        'diagnosticRuntimeFile': following[0]['plan']['runtime'],
        'diagnosticRuntimeSha256': following[0]['plan']['runtimeSha256'],
        'unrefusedDenseAdmissionAt512MiB': True, 'denseResolverCountsEqualPerFixture': True,
        'denseFactorHitCountsEqualPerFixture': True, 'normalBudgetAdmissionRedistributionObserved': True,
        'freshFollowupJvmsReconciled': 6, 'freshFollowupQueriesReconciled': 24,
        'originalReferenceQueriesReconciled': 8, 'performanceInference': False, 'javaProcessesLaunched': 0,
        'interpretation': 'Independent raw counter/result/route/page-key reconciliation. Fixture masks remain experimental. Diagnostic timings and allocations are excluded.'}
    with args.output.open('x') as stream:
        json.dump(result, stream, indent=2, sort_keys=True)
        stream.write('\n')
    if args.selection_output:
        evidence = [{'path': str(args.output.resolve()), 'sha256': raw.digest(args.output)}]
        evidence += [{'path': path, 'sha256': value} for path, value in sorted(sources.items())]
        selection = {'format': 1, 'fixtureMasks': MASKS, 'diagnosticEvidenceFiles': evidence,
            'unrefusedDenseAdmissionAt512MiB': True, 'denseResolverCountsEqualPerFixture': True,
            'status': 'Independently reconciled; root must review before using as frozen timing selection',
            'scope': 'Two exact full-consumption fixtures only; no general planner rule'}
        with args.selection_output.open('x') as stream:
            json.dump(selection, stream, indent=2, sort_keys=True)
            stream.write('\n')
    print(json.dumps({'valid': True, 'fixtures': MASKS, 'freshDiagnosticJvmsReconciled': 6,
        'output': str(args.output), 'selectionSuggestion': str(args.selection_output) if args.selection_output else None}))


if __name__ == '__main__':
    main()
